Good. Now let me create the template engine. Let me think about the interface carefully:

The TemplateEngine should:
1. Be instantiated with a templateDir (optional)
2. Load templates from the directory (layouts, partials, page templates, index template)
3. Have built-in default templates that match existing output
4. Compile and cache templates
5. Provide methods: renderPage(pageData, templateName, layoutName) and renderIndex(pagesData)

Let me think about the implementation:

```typescript
import Handlebars from 'handlebars';
import fs from 'fs';
import path from 'path';
import { PageTemplateData, IndexTemplateData } from './types';

const DEFAULT_LAYOUT = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>{{title}}</title>
</head>
<body>
  {{{body}}}
</body>
</html>`;

const DEFAULT_PAGE_TEMPLATE = `<main>
  <article>
    <h1>{{title}}</h1>
    {{#if dateFormatted}}<div class="date">{{dateFormatted}}</div>{{/if}}
    {{#if tagsStr}}<div class="tags">Tags: {{tagsStr}}</div>{{/if}}
    {{{content}}}
  </article>
</main>
<footer>
  <a href="index.html">Back to index</a>
</footer>`;

const DEFAULT_INDEX_TEMPLATE = `<main>
  <h1>Pages</h1>
  <ul>
    {{#each pages}}
    <li><a href="{{slug}}.html">{{title}}</a>{{#if dateFormatted}} — {{dateFormatted}}{{/if}}{{#if tagsStr}} [{{tagsStr}}]{{/if}}</li>
    {{/each}}
  </ul>
</main>`;

export class TemplateEngine {
  private hbs: typeof Handlebars;
  private templateDir: string | null;
  private templates: Map<string, HandlebarsTemplateDelegate>;
  private layouts: Map<string, HandlebarsTemplateDelegate>;
  private indexTemplate: HandlebarsTemplateDelegate | null;

  constructor(templateDir?: string) {
    this.hbs = Handlebars.create();
    this.templateDir = templateDir || null;
    this.templates = new Map();
    this.layouts = new Map();
    this.indexTemplate = null;

    this.compileBuiltin(DEFAULT_LAYOUT, 'default', 'layout');
    this.compileBuiltin(DEFAULT_PAGE_TEMPLATE, 'default', 'template');
    this.compileBuiltin(DEFAULT_INDEX_TEMPLATE, null, 'index');

    if (this.templateDir && fs.existsSync(this.templateDir)) {
      this.loadPartials();
      this.loadLayouts();
      this.loadTemplates();
    }
  }

  private compileBuiltin(source: string, name: string | null, type: 'layout' | 'template' | 'index'): void {
    const compiled = this.hbs.compile(source);
    if (type === 'layout' && name) {
      this.layouts.set(name, compiled);
    } else if (type === 'template' && name) {
      this.templates.set(name, compiled);
    } else if (type === 'index') {
      this.indexTemplate = compiled;
    }
  }

  private loadPartials(): void {
    const partialsDir = path.join(this.templateDir!, 'partials');
    if (!fs.existsSync(partialsDir)) return;

    const files = fs.readdirSync(partialsDir);
    for (const file of files) {
      if (file.endsWith('.hbs') || file.endsWith('.handlebars')) {
        const name = path.basename(file, path.extname(file));
        const content = fs.readFileSync(path.join(partialsDir, file), 'utf-8');
        this.hbs.registerPartial(name, content);
      }
    }
  }

  private loadLayouts(): void {
    const layoutsDir = path.join(this.templateDir!, 'layouts');
    if (!fs.existsSync(layoutsDir)) return;

    const files = fs.readdirSync(layoutsDir);
    for (const file of files) {
      if (file.endsWith('.hbs') || file.endsWith('.handlebars')) {
        const name = path.basename(file, path.extname(file));
        const content = fs.readFileSync(path.join(layoutsDir, file), 'utf-8');
        this.layouts.set(name, this.hbs.compile(content));
      }
    }
  }

  private loadTemplates(): void {
    const files = fs.readdirSync(this.templateDir!);
    for (const file of files) {
      if (file.endsWith('.hbs') || file.endsWith('.handlebars')) {
        const name = path.basename(file, path.extname(file));
        if (name === 'index') {
          const content = fs.readFileSync(path.join(this.templateDir!, file), 'utf-8');
          this.indexTemplate = this.hbs.compile(content);
        } else {
          const content = fs.readFileSync(path.join(this.templateDir!, file), 'utf-8');
          this.templates.set(name, this.hbs.compile(content));
        }
      }
    }
  }

  renderPage(data: PageTemplateData, templateName?: string, layoutName?: string): string {
    const tplName = templateName || 'default';
    const layName = layoutName || 'default';

    let template = this.templates.get(tplName);
    if (!template) {
      template = this.hbs.compile(this.getBuiltinTemplate('template', tplName));
    }

    const body = template(data);

    let layout = this.layouts.get(layName);
    if (!layout) {
      layout = this.hbs.compile(this.getBuiltinTemplate('layout', layName));
    }

    return layout({ ...data, body });
  }

  renderIndex(data: IndexTemplateData): string {
    // Use the layout for index too
    const body = this.indexTemplate!(data);
    const layout = this.layouts.get('default') || this.hbs.compile(DEFAULT_LAYOUT);
    return layout({ title: data.title, body });
  }

  private getBuiltinTemplate(type: string, name: string): string {
    if (type === 'layout') return DEFAULT_LAYOUT;
    return DEFAULT_PAGE_TEMPLATE;
  }
}
